const siteView=document.getElementById('siteView');
const appView=document.getElementById('appView');
const appContent=document.getElementById('appContent');
const crumbTitle=document.getElementById('crumbTitle');
const toastEl=document.getElementById('toast');
let currentPage='overview';
let selectedDeal='northstar';
let summaryReady=true;
let activityItems=[{title:'Deal summary drafted',detail:'Northstar Civil Ltd · by you',when:'10:42 am',icon:'S',tone:'green'},{title:'New lender response recorded',detail:'Ridgeway Equipment · by you',when:'Yesterday',icon:'H',tone:'blue'},{title:'Deal information updated',detail:'Harbour & Pine Foods · by you',when:'Sep 23',icon:'D',tone:'amber'}];
const deals={
  northstar:{name:'Northstar Civil Ltd',initial:'N',industry:'Civil construction',location:'Wellington',purpose:'Business acquisition + equipment',amount:'$2,400,000',term:'36 months',security:'Commercial property + equipment',revenue:'$5,200,000',ebitda:'$820,000',stage:0,docs:['Company overview','Management accounts','Equipment schedule','Director information','Property valuation'],matches:[['Kauri Capital','K','Strong criteria overlap','Senior secured · $1m–$5m','Property security','Business purpose','36 month term'],['Harbour Funding','H','Possible criteria overlap','Flexible credit · $500k–$3m','Property security','Established business','Working capital'],['Tui Credit Partners','T','Some criteria overlap','Asset backed · $250k–$2m','Equipment security','Business purpose','Fast assessment']]},
  harbour:{name:'Harbour & Pine Foods',initial:'H',industry:'Food manufacturing',location:'Auckland',purpose:'Seasonal working capital',amount:'$850,000',term:'24 months',security:'Inventory + director support',revenue:'$3,100,000',ebitda:'$410,000',stage:1,docs:['Company overview','Management accounts','Sales forecast','Director information','Inventory schedule'],matches:[['Harbour Funding','H','Strong criteria overlap','Flexible credit · $500k–$3m','Working capital','Established business','24 month term'],['Kauri Capital','K','Possible criteria overlap','Senior secured · $1m–$5m','Property security','Business purpose','Established business'],['Tui Credit Partners','T','Some criteria overlap','Asset backed · $250k–$2m','Inventory security','Working capital','Fast assessment']]},
  ridge:{name:'Ridgeway Equipment Ltd',initial:'R',industry:'Agricultural services',location:'Canterbury',purpose:'Equipment purchase',amount:'$1,200,000',term:'48 months',security:'Equipment being financed',revenue:'$4,600,000',ebitda:'$690,000',stage:2,docs:['Company overview','Management accounts','Equipment quote','Director information','Cash flow forecast'],matches:[['Tui Credit Partners','T','Strong criteria overlap','Asset backed · $250k–$2m','Equipment security','Business purpose','Established business'],['Kauri Capital','K','Possible criteria overlap','Senior secured · $1m–$5m','Equipment security','Business purpose','36 month term'],['Harbour Funding','H','Some criteria overlap','Flexible credit · $500k–$3m','Equipment security','Established business','48 month term']]}
};
function notify(message){toastEl.textContent=message;toastEl.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>toastEl.classList.remove('show'),2400)}
function openDemo(){siteView.classList.add('hidden');appView.classList.remove('hidden');showPage('overview');window.scrollTo(0,0)}
function goHome(){appView.classList.add('hidden');siteView.classList.remove('hidden');window.scrollTo(0,0)}
function wireCommon(){document.querySelectorAll('[data-open-demo]').forEach(b=>b.addEventListener('click',openDemo));document.getElementById('backHome').addEventListener('click',e=>{e.preventDefault();goHome()});document.getElementById('resetDemo').addEventListener('click',()=>{summaryReady=true;activityItems=activityItems.slice(0,3);showPage('overview');notify('Sample workspace reset')});document.getElementById('helpButton')?.addEventListener('click',()=>notify('This demo uses fictional data and illustrative lender criteria.'))}
function showPage(page){currentPage=page;const titles={overview:'Overview',deals:'Deals',lenders:'Lender criteria',activity:'Activity'};crumbTitle.textContent=titles[page]||'Deal details';document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.page===page));if(page==='overview')renderOverview();else if(page==='deals')renderDeals();else if(page==='lenders')renderLenders();else if(page==='activity')renderActivity();}
function openDeal(id){selectedDeal=id;renderDeal();}
function activityMarkup(items){return items.map(x=>`<div class="activity-item"><span class="activity-avatar activity-avatar-${x.tone}">${x.icon}</span><div><b>${x.title}</b><p>${x.detail}</p></div><time>${x.when}</time></div>`).join('')}
function renderOverview(){appContent.innerHTML=`<div class="welcome-row"><div><div class="eyebrow">THURSDAY, 25 SEPTEMBER 2026</div><h1>Good evening, Ollie <span class="wave">✳</span></h1><p>Here’s where your deals are at today.</p></div><button class="button button-dark" id="newDeal"><span>＋</span> New deal</button></div><div class="stat-grid"><div class="stat-card"><div class="stat-top"><span>Active deals</span><span class="stat-icon">▣</span></div><div class="stat-value">03</div><div class="stat-caption"><span class="green-dot"></span> Across your workspace</div></div><div class="stat-card"><div class="stat-top"><span>Needs your attention</span><span class="stat-icon stat-icon-amber">◷</span></div><div class="stat-value">02</div><div class="stat-caption">Follow-ups or information due</div></div><div class="stat-card"><div class="stat-top"><span>Potential lender fits</span><span class="stat-icon stat-icon-blue">⌁</span></div><div class="stat-value">07</div><div class="stat-caption">Across active sample deals</div></div></div><div class="dashboard-grid"><section class="panel deals-panel"><div class="panel-heading"><div><h2>Your deals</h2><p>Keep track of what’s moving.</p></div><button class="subtle-button" data-page="deals">View all <span>↗</span></button></div><div class="deal-table-wrap"><table class="deal-table"><thead><tr><th>COMPANY</th><th>FINANCE SOUGHT</th><th>STATUS</th><th>UPDATED</th><th></th></tr></thead><tbody>${Object.entries(deals).map(([id,d])=>`<tr class="deal-row" data-deal="${id}"><td><span class="table-company"><i class="company-icon">${d.initial}</i><span><b>${d.name}</b><small>${d.location} · ${d.purpose.split(' ')[0]}</small></span></span></td><td><b>${d.amount}</b></td><td><span class="table-status status-${['preparing','review','waiting'][d.stage]}">● ${['Preparing','In review','With lender'][d.stage]}</span></td><td>${id==='northstar'?'Today':id==='harbour'?'Yesterday':'Sep 22'}</td><td>↗</td></tr>`).join('')}</tbody></table></div><button class="mobile-deal" data-deal="northstar"><b>Northstar Civil Ltd</b><span>$2,400,000 · Preparing ↗</span></button></section><section class="panel attention-panel"><div class="panel-heading"><div><h2>Next steps</h2><p>A couple of things to keep moving.</p></div><span class="attention-count">2</span></div><div class="task-item"><span class="task-icon task-doc">▤</span><span><b>Confirm property valuation</b><small>Northstar Civil · Missing document</small></span><button class="task-arrow" data-deal="northstar">↗</button></div><div class="task-item"><span class="task-icon task-follow">↗</span><span><b>Check in with lender</b><small>Ridgeway Equipment · Due today</small></span><button class="task-arrow" data-deal="ridge">↗</button></div><div class="panel-footer">DEMO TASKS <span>↗</span></div></section></div><div class="bottom-grid"><section class="panel activity-panel"><div class="panel-heading"><div><h2>Recent activity</h2><p>Updates across your deals.</p></div><button class="subtle-button" data-page="activity">See activity <span>↗</span></button></div>${activityMarkup(activityItems.slice(0,3))}</section><section class="insight-card"><span class="insight-icon">✳</span><span class="insight-label">A CLEARER WAY FORWARD</span><h3>Every deal has a next step.</h3><p>Keep the details, lender conversations and follow-ups moving in one place.</p><button data-deal="northstar">Open Northstar deal <span>↗</span></button></section></div><div class="app-disclaimer">Mandate is an adviser workflow concept. Lender matches shown are illustrative criteria comparisons, not credit decisions or offers.</div>`;bindPage()}
function renderDeal(){const d=deals[selectedDeal];const stageNames=['Preparing deal','Adviser review','With lender','Outcome recorded'];crumbTitle.textContent='Deal details';const fitCards=d.matches.map((m,i)=>`<div class="lender-card"><div class="lender-title"><span class="lender-logo">${m[1]}</span><b>${m[0]}</b><span class="fit-label">${m[2]}</span></div><p>${i===0?'Several recorded criteria align with this deal.':'Potential fit based on the details provided; confirm all lender requirements directly.'}</p><div class="lender-criteria">${m.slice(3).map(t=>`<span>${t}</span>`).join('')}</div><button class="view-lender" data-lender="${m[0]}">View comparison ↗</button></div>`).join('');const docs=d.docs.map((doc,i)=>`<div class="document-row"><span class="document-icon">▤</span><span><b>${doc}</b><small>${i===0?'Company file · demo item':'Example placeholder · no file attached'}</small></span><span class="doc-status ${i===4?'missing':''}">${i===4?'Needed':'Added'}</span></div>`).join('');const stages=stageNames.map((x,i)=>`<div class="stage-row ${i<d.stage?'complete':i===d.stage?'current':''}"><span class="stage-dot">${i<d.stage?'✓':''}</span><span class="stage-copy"><b>${x}</b><small>${i<d.stage?'Marked complete':i===d.stage?'Current stage':'Not started'}</small></span></div>`).join('');appContent.innerHTML=`<button class="detail-back" id="backToDeals">← Back to deals</button><div class="detail-head"><div class="detail-company"><span class="company-icon">${d.initial}</span><div><h1>${d.name}</h1><p>${d.location} · ${d.industry} <span class="table-status status-${['preparing','review','waiting'][d.stage]}">● ${['Preparing','In review','With lender'][d.stage]}</span></p></div></div><div class="detail-actions"><button class="button-outline" id="addNote">＋ Add note</button><button class="button button-dark" id="advanceDeal">Move to next step <span>↗</span></button></div></div><div class="detail-layout"><div class="detail-column"><section class="detail-card"><div class="detail-card-title"><h2>Deal overview</h2><button id="editDeal">Edit details ↗</button></div><div class="overview-facts"><div class="fact"><small>FINANCE SOUGHT</small><b>${d.amount}</b></div><div class="fact"><small>PURPOSE</small><b>${d.purpose}</b></div><div class="fact"><small>TERM REQUESTED</small><b>${d.term}</b></div><div class="fact"><small>SECURITY</small><b>${d.security}</b></div><div class="fact"><small>ANNUAL REVENUE</small><b>${d.revenue}</b></div><div class="fact"><small>EBITDA</small><b>${d.ebitda}</b></div></div></section><section class="detail-card"><div class="detail-card-title"><h2>Deal summary</h2><button id="draftSummary">${summaryReady?'Refresh draft':'Draft summary'} ↗</button></div><div class="summary-box"><b>${d.name}</b> is seeking ${d.amount} over ${d.term} to support ${d.purpose.toLowerCase()}. The business operates in ${d.industry.toLowerCase()} from ${d.location}. Recorded annual revenue is ${d.revenue} with EBITDA of ${d.ebitda}. Proposed security is ${d.security.toLowerCase()}. <b>Items for adviser review:</b> confirm valuation, verify current financial information and check lender-specific requirements before sharing.</div><div class="summary-meta"><span>Generated from sample deal details · Review before use</span><span class="draft-label">DRAFT</span></div></section><section class="detail-card"><div class="detail-card-title"><h2>Deal pack checklist</h2><button id="addDocument">＋ Add item</button></div>${docs}</section></div><div class="detail-column"><section class="detail-card"><div class="detail-card-title"><h2>Potential lender fit</h2><button data-page="lenders">All criteria ↗</button></div><p class="match-intro">Illustrative comparison of recorded deal details against fictional lender criteria. Not a credit decision.</p>${fitCards}</section><section class="detail-card"><div class="detail-card-title"><h2>Deal progress</h2><button id="stageMenu">Update ↗</button></div><div class="stage-list">${stages}</div></section><section class="detail-card"><div class="detail-card-title"><h2>Recent activity</h2></div>${activityMarkup(activityItems.slice(0,2))}</section></div></div><div class="app-disclaimer">All companies and lender names are fictional. Criteria comparisons are illustrative and require adviser verification.</div>`;document.getElementById('backToDeals').onclick=()=>showPage('deals');document.getElementById('advanceDeal').onclick=()=>advanceStage();document.getElementById('draftSummary').onclick=()=>{summaryReady=true;activityItems.unshift({title:'Deal summary refreshed',detail:d.name+' · by you',when:'Just now',icon:d.initial,tone:'green'});renderDeal();notify('Draft summary is ready for adviser review')};document.getElementById('editDeal').onclick=()=>notify('Deal details are sample data in this prototype.');document.getElementById('addNote').onclick=()=>notify('Notes will be part of a later prototype step.');document.getElementById('addDocument').onclick=()=>notify('Document upload is not enabled in the sample demo.');document.getElementById('stageMenu').onclick=()=>advanceStage();bindCommonClicks()}
function advanceStage(){const d=deals[selectedDeal];d.stage=Math.min(3,d.stage+1);activityItems.unshift({title:'Deal stage updated',detail:d.name+' · by you',when:'Just now',icon:d.initial,tone:'green'});renderDeal();notify(d.stage===3?'Deal marked outcome recorded':'Deal moved to '+['Preparing deal','Adviser review','With lender'][d.stage])}
function renderDeals(){crumbTitle.textContent='Deals';appContent.innerHTML=`<div class="page-title"><div><div class="eyebrow">YOUR WORKSPACE</div><h1>Deals</h1><p>Keep the important details and next steps together.</p></div><button class="button button-dark" id="newDeal"><span>＋</span> New deal</button></div><div class="filter-row"><button class="filter-chip active">All deals <b>3</b></button><button class="filter-chip">Preparing <b>1</b></button><button class="filter-chip">In review <b>1</b></button><button class="filter-chip">With lender <b>1</b></button></div><section class="panel table-overflow"><table class="full-table"><thead><tr><th>COMPANY</th><th>FINANCE SOUGHT</th><th>PURPOSE</th><th>STATUS</th><th>NEXT STEP</th><th></th></tr></thead><tbody>${Object.entries(deals).map(([id,d])=>`<tr data-deal="${id}"><td><span class="table-company"><i class="company-icon">${d.initial}</i><span><b>${d.name}</b><small>${d.location} · ${d.industry}</small></span></span></td><td><b>${d.amount}</b></td><td>${d.purpose}</td><td><span class="table-status status-${['preparing','review','waiting'][d.stage]}">● ${['Preparing','In review','With lender'][d.stage]}</span></td><td>${['Confirm deal information','Review deal pack','Follow up with lender'][d.stage]}</td><td>↗</td></tr>`).join('')}</tbody></table></section><div class="app-disclaimer">Fictional demo data only · No real borrower or lender information.</div>`;bindPage();document.getElementById('newDeal').onclick=()=>notify('Creating a new deal is outside this demo flow.')}
function renderLenders(){crumbTitle.textContent='Lender criteria';const d=deals[selectedDeal];appContent.innerHTML=`<div class="page-title"><div><div class="eyebrow">ILLUSTRATIVE DIRECTORY</div><h1>Lender criteria</h1><p>Compare fictional lender preferences with the selected sample deal.</p></div><button class="button-outline" data-page="deals">Change deal ↗</button></div><div class="filter-row"><button class="filter-chip active">All lenders</button><button class="filter-chip">Secured lending</button><button class="filter-chip">Asset finance</button><button class="filter-chip">Working capital</button></div><div class="lender-grid">${d.matches.map(m=>`<div class="lender-card"><div class="lender-title"><span class="lender-logo">${m[1]}</span><b>${m[0]}</b><span class="fit-label">${m[2]}</span></div><p>Example private credit provider profile. Review the full deal and confirm current lending criteria with the lender directly.</p><div class="lender-criteria">${m.slice(3).map(x=>`<span>${x}</span>`).join('')}</div><button class="view-lender" data-lender="${m[0]}">View criteria comparison ↗</button></div>`).join('')}</div><div class="lender-note"><b>How this comparison works:</b> It shows which example criteria overlap with the details entered for ${d.name}. It does not rank creditworthiness, predict approval, provide an offer, or contact lenders. The adviser remains responsible for verifying fit and deciding what to do next.</div>`;bindPage()}
function renderActivity(){crumbTitle.textContent='Activity';appContent.innerHTML=`<div class="page-title"><div><div class="eyebrow">WORKSPACE HISTORY</div><h1>Activity</h1><p>Recent updates across your sample deals.</p></div></div><div class="activity-feed">${activityMarkup(activityItems.concat([{title:'Deal created',detail:'Northstar Civil Ltd · sample workspace',when:'Sep 20',icon:'N',tone:'green'},{title:'Lender criteria reviewed',detail:'Kauri Capital · sample workspace',when:'Sep 20',icon:'K',tone:'blue'}]))}</div><div class="app-disclaimer">Activity is held only in this browser session and uses fictional sample details.</div>`}
function bindCommonClicks(){appContent.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>showPage(el.dataset.page)));appContent.querySelectorAll('[data-lender]').forEach(el=>el.addEventListener('click',()=>notify('Illustrative match: check the lender’s current criteria directly.')))}
function bindPage(){bindCommonClicks();appContent.querySelectorAll('[data-deal]').forEach(el=>el.addEventListener('click',()=>openDeal(el.dataset.deal)));appContent.querySelectorAll('.nav-item').forEach(el=>el.onclick=()=>showPage(el.dataset.page));}
function showPage(page){currentPage=page;const titles={overview:'Overview',deals:'Deals',lenders:'Lender criteria',activity:'Activity'};crumbTitle.textContent=titles[page]||'Deal details';document.querySelectorAll('.nav-item').forEach(el=>{el.classList.toggle('active',el.dataset.page===page);el.onclick=()=>showPage(el.dataset.page)});if(page==='overview')renderOverview();else if(page==='deals')renderDeals();else if(page==='lenders')renderLenders();else if(page==='activity')renderActivity();}
wireCommon();
